// What the session spent before the meter watched: read back from its
// transcripts (the main thread's, each subagent's, each workflow agent's),
// every response priced exactly as Claude Code prices it.

import type { ModelUsage } from 'claude-code'

import type { SpendAgentMeta, SpendCompaction, SpendSeries, SpendSources } from '../types'
import { addStep, addToSeries, attribute, EMPTY_SERIES, EMPTY_SOURCES, finishAgent } from './ledger'
import { partsTotal, priceRaw } from './pricing'
import type { RawUsage } from './pricing'

export type TranscriptFile = { agentId?: string; meta?: SpendAgentMeta; text: string }

export type Rebuilt = {
  sources: SpendSources
  series: SpendSeries
  usd: number
  responses: number
  /** The last prompt's turn: when it began and ended, and what it cost. */
  turn?: { startedAt: number; endedAt: number; usd: number }
  compactions: SpendCompaction[]
}

type Billed = { at: number; agentId?: string; model: string; usage: RawUsage }

const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0)

// A response is written once per content block, each row carrying its usage
// as of then: the largest of each count is the response's.
function merge(a: RawUsage, b: RawUsage): RawUsage {
  return {
    input_tokens: Math.max(num(a.input_tokens), num(b.input_tokens)),
    output_tokens: Math.max(num(a.output_tokens), num(b.output_tokens)),
    cache_read_input_tokens: Math.max(num(a.cache_read_input_tokens), num(b.cache_read_input_tokens)),
    cache_creation_input_tokens: Math.max(num(a.cache_creation_input_tokens), num(b.cache_creation_input_tokens)),
    cache_creation: {
      ephemeral_5m_input_tokens: Math.max(
        num(a.cache_creation?.ephemeral_5m_input_tokens),
        num(b.cache_creation?.ephemeral_5m_input_tokens),
      ),
      ephemeral_1h_input_tokens: Math.max(
        num(a.cache_creation?.ephemeral_1h_input_tokens),
        num(b.cache_creation?.ephemeral_1h_input_tokens),
      ),
    },
    server_tool_use: {
      web_search_requests: Math.max(
        num(a.server_tool_use?.web_search_requests),
        num(b.server_tool_use?.web_search_requests),
      ),
    },
    inference_geo: b.inference_geo ?? a.inference_geo,
  }
}

const asModelUsage = (u: RawUsage): ModelUsage => ({
  input_tokens: num(u.input_tokens),
  output_tokens: num(u.output_tokens),
  cache_read_input_tokens: num(u.cache_read_input_tokens),
  cache_creation_input_tokens: num(u.cache_creation_input_tokens),
})

/** Whether a user row is a prompt the person sent, not a tool result or a note. */
function isPrompt(row: { isMeta?: unknown; isSidechain?: unknown; isCompactSummary?: unknown; message?: { content?: unknown } }) {
  if (row.isMeta === true || row.isSidechain === true || row.isCompactSummary === true) return false
  const content = row.message?.content
  if (typeof content === 'string') return !content.startsWith('<local-command') && !content.startsWith('Caveat:')
  return (
    Array.isArray(content) &&
    content.some(b => (b as { type?: unknown }).type === 'text') &&
    !content.some(b => (b as { type?: unknown }).type === 'tool_result')
  )
}

/** The ledger the transcripts add up to, counting responses up to `cutoff`. */
export function rebuild(files: readonly TranscriptFile[], cutoff: number): Rebuilt {
  const agents: Record<string, SpendAgentMeta> = {}
  for (const f of files) if (f.agentId !== undefined && f.meta !== undefined) agents[f.agentId] = f.meta
  const billed: Billed[] = []
  const compactions: SpendCompaction[] = []
  let promptAt: number | undefined
  for (const f of files) {
    const byId = new Map<string, Billed>()
    for (const line of f.text.split('\n')) {
      const isMain = f.agentId === undefined
      const isUser = isMain && line.includes('"type":"user"')
      const isCompaction = isMain && line.includes('"compact_boundary"')
      if (!isUser && !isCompaction && !line.includes('"type":"assistant"')) continue
      let row: Record<string, unknown>
      try {
        row = JSON.parse(line) as Record<string, unknown>
      } catch {
        continue // a torn last line, or a chunk's edge
      }
      const at = Date.parse(String(row['timestamp']))
      if (!Number.isFinite(at) || at > cutoff) continue
      if (row['subtype'] === 'compact_boundary') {
        const meta = row['compactMetadata'] as { trigger?: string; preTokens?: number; postTokens?: number } | undefined
        compactions.push({ at, trigger: meta?.trigger ?? 'auto', from: meta?.preTokens, to: meta?.postTokens })
        continue
      }
      if (row['type'] === 'user') {
        if (isPrompt(row as Parameters<typeof isPrompt>[0])) promptAt = at
        continue
      }
      if (row['type'] !== 'assistant') continue
      const m = row['message'] as { id?: string; model?: string; usage?: RawUsage } | undefined
      if (m?.usage === undefined || m.model === undefined || m.model === '<synthetic>') continue
      const id = m.id ?? String(row['requestId'] ?? row['uuid'])
      const prev = byId.get(id)
      byId.set(
        id,
        prev === undefined
          ? { at, agentId: f.agentId, model: m.model, usage: m.usage }
          : { ...prev, at: Math.max(prev.at, at), usage: merge(prev.usage, m.usage) },
      )
    }
    billed.push(...byId.values())
  }
  billed.sort((a, b) => a.at - b.at)

  let sources: SpendSources = { ...EMPTY_SOURCES, agents }
  let series: SpendSeries = EMPTY_SERIES
  let usd = 0
  let turnUsd = 0
  let lastAt = 0
  for (const b of billed) {
    const parts = priceRaw(b.model, b.usage)
    const who = attribute(b.agentId, sources)
    sources = addStep(sources, who, b.model, asModelUsage(b.usage), parts, b.at)
    const c = parts === undefined ? 0 : partsTotal(parts)
    usd += c
    series = addToSeries(series, b.at, {
      main: who.kind === 'main' ? c : 0,
      agents: who.kind === 'agent' || who.kind === 'fork' ? c : 0,
      workflows: who.kind === 'workflow' ? c : 0,
    })
    if (promptAt !== undefined && b.at >= promptAt) turnUsd += c
    lastAt = b.at
  }
  for (const id of Object.keys(agents)) sources = finishAgent(sources, id, 'done')
  return {
    sources,
    series,
    usd,
    responses: billed.length,
    turn: promptAt === undefined ? undefined : { startedAt: promptAt, endedAt: Math.max(lastAt, promptAt), usd: turnUsd },
    compactions: compactions.slice(-20),
  }
}

files.hooks/pricing.ts:
// List prices per million tokens, as Claude Code 2.1.300's own model catalog
// has them (the same table /cost prices with), and the step pricing it does.
// The engine hands a mod the session's total but not each response's dollars,
// so this prices each response to say who spent what; the total stays the
// engine's.

import type { ModelUsage } from 'claude-code'

type Rates = { in: number; out: number; w5m: number; w1h: number; read: number }
type Tier = Rates & { long?: Rates & { above: number } }

const tier = (input: number, output: number, read = input / 10): Tier => ({
  in: input,
  out: output,
  w5m: input * 1.25,
  w1h: input * 2,
  read,
})

const TIERS = {
  haiku_35: tier(0.8, 4),
  haiku_45: tier(1, 5),
  haiku_55: { ...tier(0.1, 0.5), long: { ...tier(0.5, 2.5), above: 100_000 } },
  tier_2_10: tier(2, 10),
  tier_2_10_cr_010: tier(2, 10, 0.1),
  tier_3_15: tier(3, 15),
  tier_4_20_cr_020: tier(4, 20, 0.2),
  tier_5_25: tier(5, 25),
  tier_10_50: tier(10, 50),
  tier_10_50_cr_025: tier(10, 50, 0.25),
  tier_15_75: tier(15, 75),
} satisfies Record<string, Tier>

const CATALOG: Record<string, { name: string; tier: keyof typeof TIERS }> = {
  'claude-3-5-haiku': { name: 'Haiku 3.5', tier: 'haiku_35' },
  'claude-haiku-4-5': { name: 'Haiku 4.5', tier: 'haiku_45' },
  'claude-haiku-5-5': { name: 'Haiku 5.5', tier: 'haiku_55' },
  'claude-3-5-sonnet': { name: 'Sonnet 3.5', tier: 'tier_3_15' },
  'claude-3-7-sonnet': { name: 'Sonnet 3.7', tier: 'tier_3_15' },
  'claude-sonnet-4-0': { name: 'Sonnet 4', tier: 'tier_3_15' },
  'claude-sonnet-4-5': { name: 'Sonnet 4.5', tier: 'tier_3_15' },
  'claude-sonnet-4-6': { name: 'Sonnet 4.6', tier: 'tier_3_15' },
  'claude-sonnet-5': { name: 'Sonnet 5', tier: 'tier_2_10' },
  'claude-sonnet-5-5': { name: 'Sonnet 5.5', tier: 'tier_2_10_cr_010' },
  'claude-opus-4-0': { name: 'Opus 4', tier: 'tier_15_75' },
  'claude-opus-4-1': { name: 'Opus 4.1', tier: 'tier_15_75' },
  'claude-opus-4-5': { name: 'Opus 4.5', tier: 'tier_5_25' },
  'claude-opus-4-6': { name: 'Opus 4.6', tier: 'tier_5_25' },
  'claude-opus-4-7': { name: 'Opus 4.7', tier: 'tier_5_25' },
  'claude-opus-4-8': { name: 'Opus 4.8', tier: 'tier_5_25' },
  'claude-opus-5': { name: 'Opus 5', tier: 'tier_5_25' },
  'claude-opus-5-5': { name: 'Opus 5.5', tier: 'tier_4_20_cr_020' },
  'claude-fable-5': { name: 'Fable 5', tier: 'tier_10_50' },
  'claude-fable-5-1': { name: 'Fable 5.1', tier: 'tier_10_50_cr_025' },
  'claude-mythos-5': { name: 'Mythos 5', tier: 'tier_10_50' },
  'claude-mythos-5-1': { name: 'Mythos 5.1', tier: 'tier_10_50_cr_025' },
}

// Longest first, so `claude-opus-5-5` wins over `claude-opus-5`.
const IDS = Object.keys(CATALOG).sort((a, b) => b.length - a.length)

/**
 * The catalog id a reported model id names: a dated id
 * (`claude-opus-5-5-20261001`), a provider's (`us.anthropic.claude-...-v1:0`)
 * or one with a context suffix (`claude-fable-5-1[1m]`).
 */
export function catalogId(model: string | undefined): string | undefined {
  if (model === undefined) return undefined
  const id = model.toLowerCase()
  for (const known of IDS) {
    const at = id.indexOf(known)
    if (at < 0) continue
    const before = id[at - 1]
    const rest = id.slice(at + known.length)
    if (before !== undefined && /[a-z0-9]/.test(before)) continue
    // `-5` after `claude-opus-5` is another model; `-20261001` is a date.
    if (/^-\d(\D|$)/.test(rest) || /^\d/.test(rest)) continue
    return known
  }
  return undefined
}

export function modelName(model: string | undefined): string {
  const id = catalogId(model)
  if (id !== undefined) return CATALOG[id]?.name ?? id
  if (model === undefined || model === '') return '?'
  return model.replace(/^claude-/, '')
}

/** USD per million output tokens, for pricing what is still streaming. */
export function outputRate(model: string | undefined): number {
  const id = catalogId(model)
  return id === undefined ? 0 : (TIERS[CATALOG[id]!.tier].out ?? 0)
}

/** USD per million uncached input tokens: what input would cost without the cache. */
export function inputRate(model: string | undefined): number {
  const id = catalogId(model)
  return id === undefined ? 0 : TIERS[CATALOG[id]!.tier].in
}

/** USD per million cache-read tokens: what re-reading the context costs. */
export function readRate(model: string | undefined): number {
  const id = catalogId(model)
  return id === undefined ? 0 : TIERS[CATALOG[id]!.tier].read
}

/** A response's usage as the transcript records it: the API's own fields. */
export type RawUsage = {
  input_tokens?: number
  output_tokens?: number
  cache_read_input_tokens?: number
  cache_creation_input_tokens?: number
  cache_creation?: { ephemeral_5m_input_tokens?: number; ephemeral_1h_input_tokens?: number }
  server_tool_use?: { web_search_requests?: number }
  inference_geo?: string
}

/**
 * What a response cost, by what was paid for: `output` the tokens the model
 * wrote, `write` new input stored in the prompt cache, `read` input served
 * from it, `input` input never cached (web searches count here too).
 */
export type Parts = { input: number; output: number; read: number; write: number }

export const NO_PARTS: Parts = { input: 0, output: 0, read: 0, write: 0 }

export const partsTotal = (p: Parts) => p.input + p.output + p.read + p.write

export function addParts(a: Parts, b: Parts | undefined): Parts {
  if (b === undefined) return a
  return { input: a.input + b.input, output: a.output + b.output, read: a.read + b.read, write: a.write + b.write }
}

function rates(model: string | undefined, prompt: number): Rates | undefined {
  const id = catalogId(model)
  if (id === undefined) return undefined
  const base: Tier = TIERS[CATALOG[id]!.tier]
  return base.long !== undefined && prompt > base.long.above ? base.long : base
}

/**
 * What a transcript's response cost, priced as Claude Code prices it: the
 * cache writes split by their TTL, US-only inference at 1.1×, web searches
 * at a cent each. Undefined for a model the catalog lacks.
 */
export function priceRaw(model: string | undefined, u: RawUsage): Parts | undefined {
  const input = u.input_tokens ?? 0
  const read = u.cache_read_input_tokens ?? 0
  const written = u.cache_creation_input_tokens ?? 0
  const r = rates(model, input + read + written)
  if (r === undefined) return undefined
  const w1h = Math.min(u.cache_creation?.ephemeral_1h_input_tokens ?? 0, written)
  const k = (u.inference_geo === 'us' ? 1.1 : 1) / 1e6
  return {
    input: input * r.in * k + (u.server_tool_use?.web_search_requests ?? 0) * 0.01,
    output: (u.output_tokens ?? 0) * r.out * k,
    read: read * r.read * k,
    write: (w1h * r.w1h + (written - w1h) * r.w5m) * k,
  }
}

/**
 * What one response cost at list price, or undefined for a model the catalog
 * lacks. `ttl` is how long the prompt cache was written for: Claude Code
 * writes the main thread's for an hour on a subscription, a subagent's for
 * five minutes.
 */
export function priceUsage(model: string | undefined, usage: ModelUsage, ttl: '5m' | '1h'): Parts | undefined {
  const prompt = usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens
  const r = rates(model, prompt)
  if (r === undefined) return undefined
  return {
    input: (usage.input_tokens * r.in) / 1e6,
    output: (usage.output_tokens * r.out) / 1e6,
    read: (usage.cache_read_input_tokens * r.read) / 1e6,
    write: (usage.cache_creation_input_tokens * (ttl === '1h' ? r.w1h : r.w5m)) / 1e6,
  }
}

files.hooks/view.tsx:
// The pane's drawing: a tree from the meter's state, sized to the pane body.

import type { Elements, RenderElement, RenderSurface } from 'claude-code'

import type { SpendCompaction, SpendCore, SpendLive, SpendPrefs, SpendSeries, SpendSource, SpendSources } from '../types'
import { areaCells, areaPixels, areaText } from './art'
import {
  barsOf,
  barTotal,
  burnPerMin,
  cacheHit,
  clip,
  fmtDur,
  fmtEta,
  fmtMin,
  fmtPct,
  fmtTok,
  fmtUsd,
  gauge,
  hex,
  pace,
  packCells,
  PALETTE,
  sumCost,
  sumTokens,
  windowMoved,
} from './ledger'
import { inputRate, modelName, readRate } from './pricing'

export const UNITS = [
  { id: 'usd', label: 'this session · USD at API list price' },
  { id: 'tok', label: 'tokens through the models this session' },
  { id: 'coffee', label: 'flat whites at $4.50', per: 4.5, glyph: '☕ ' },
  { id: 'banana', label: 'bananas, for scale', per: 0.3, glyph: '🍌 ' },
  { id: 'dev', label: 'minutes of a senior engineer', per: 1.5, glyph: '' },
] as const

const KIND_COLOR = {
  main: hex(PALETTE.main),
  agent: hex(PALETTE.agents),
  workflow: hex(PALETTE.workflows),
  fork: hex(PALETTE.other),
}

const KIND_NAME = { main: 'main thread', agent: 'subagents', workflow: 'workflows' } as const

const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

export type ViewData = {
  now: number
  core: SpendCore | null
  sources: SpendSources
  series: SpendSeries
  prefs: SpendPrefs
  live: SpendLive
  width: number
  rows: number
  placement: 'dock' | 'inline'
  surface: RenderSurface
  viewedAgentId?: string
  /** Whether the chart may be a kitty-protocol picture rather than cells. */
  gfx: 'cells' | 'pixels'
  caps: Caps
}

export type ViewActions = {
  cycleUnit: () => void
  select: (key: string | null) => void
  /** Puts an agent's transcript in the main view; undefined goes back to the main one. */
  view: (agentId: string | undefined) => void
}

/** What the engine the meter runs in can draw and do, as its version says. */
export type Caps = {
  /** Text `weight`, `size`, `tabular` and `mono`, since 2.1.299; an older engine refuses a tree that names them. */
  textStyles: boolean
  /** `$.ui.view`, since 2.1.300. */
  agentView: boolean
}

export const OLD_ENGINE: Caps = { textStyles: false, agentView: false }

export function capsOf(v: { version: string; base?: string } | undefined): Caps {
  const m = /^(\d+)\.(\d+)\.(\d+)/.exec(v?.base ?? v?.version ?? '')
  if (m === null) return OLD_ENGINE
  const n = Number(m[1]) * 1e6 + Number(m[2]) * 1e3 + Number(m[3])
  return { textStyles: n >= 2_001_299, agentView: n >= 2_001_300 }
}

/** Text styles as the engine spells them: bold was `bold` before 2.1.299, `weight` since. */
function looksOf(caps: Caps) {
  return caps.textStyles
    ? ({ strong: { weight: 'semibold' }, hero: { weight: 'semibold', size: 'heading', tabular: true }, num: { tabular: true }, table: { mono: true } } as const)
    : ({ strong: { bold: true }, hero: { bold: true }, num: {}, table: {} } as const)
}
type Looks = ReturnType<typeof looksOf>

type Ui = Elements[RenderSurface]
/** The terminal's own elements: cells colored one by one, and pictures. */
export type Art = { Raster: Elements['terminal']['Raster']; Image: Elements['terminal']['Image'] }

type Row = {
  key: string
  kind: SpendSource['kind'] | 'overhead' | 'earlier'
  label: string
  usd: number
  status?: SpendSource['status']
  isStreaming: boolean
  source?: SpendSource
}

const pctColor = (pct: number) => (pct >= 80 ? 'error' : pct >= 50 ? 'warning' : 'success')

function windowName(kind: string): string {
  if (kind === 'five_hour') return '5h'
  if (kind === 'seven_day') return '7d'
  if (kind === 'spend_limit') return '$'
  if (kind.startsWith('seven_day_')) return `7d${kind.slice(10, 11)}`
  return kind.slice(0, 3)
}

/** How good a cache hit rate is, said in a word. */
function hitWord(hit: number): [string, string] {
  if (hit >= 0.95) return ['excellent', 'success']
  if (hit >= 0.85) return ['good', 'success']
  if (hit >= 0.7) return ['fair', 'warning']
  return ['poor', 'error']
}

/** The rows of "where it goes", the engine's total split as far as it can be. */
export function rowsOf(d: ViewData): Row[] {
  const live = new Set(d.live.keys)
  const rows: Row[] = Object.values(d.sources.rows).map(s => ({
    key: s.key,
    kind: s.kind,
    label: s.kind === 'main' ? `main thread · ${modelName(s.model)}` : s.kind === 'fork' ? 'compaction & memory' : s.label,
    usd: s.usd,
    status: s.status,
    isStreaming: live.has(s.key),
    source: s,
  }))
  const order = (r: Row) => (r.kind === 'main' ? 0 : r.kind === 'fork' ? 3 : r.status === 'running' ? 1 : 2)
  rows.sort((a, b) => order(a) - order(b) || b.usd - a.usd)
  if (d.core !== null) {
    const priced = rows.reduce((a, r) => a + r.usd, 0)
    const overhead = d.core.usd - d.core.usd0 - priced
    if (overhead >= 0.0005) {
      rows.push({ key: 'overhead', kind: 'overhead', label: 'side calls: classifier, titles', usd: overhead, isStreaming: false })
    }
    if (d.core.usd0 >= 0.0005) {
      rows.push({ key: 'earlier', kind: 'earlier', label: 'before the meter', usd: d.core.usd0, isStreaming: false })
    }
  }
  return rows
}

function glyphOf(r: Row, tick: number): string {
  if (r.isStreaming) return SPINNER[tick % SPINNER.length]!
  if (r.kind === 'overhead') return '◇'
  if (r.kind === 'earlier') return '·'
  if (r.kind === 'fork') return '○'
  if (r.status === 'done') return '✓'
  if (r.status === 'failed') return '✗'
  return r.kind === 'workflow' ? '◆' : '●'
}

function colorOf(r: Row): string {
  if (r.kind === 'overhead' || r.kind === 'earlier') return 'subtle'
  return KIND_COLOR[r.kind]
}

function heroValue(d: ViewData, tokens: number): { text: string; caption: string } {
  const unit = UNITS[d.prefs.unit % UNITS.length]!
  const usd = d.core?.usd ?? 0
  if (unit.id === 'usd') return { text: fmtUsd(usd), caption: unit.label }
  if (unit.id === 'tok') return { text: fmtTok(tokens), caption: unit.label }
  const n = usd / unit.per
  return { text: `${unit.glyph}${n >= 100 ? n.toFixed(0) : n.toFixed(1)}`, caption: `${unit.label} · ${fmtUsd(usd)}` }
}

function compactionNote(list: readonly SpendCompaction[] | undefined, now: number): string | undefined {
  const last = list?.at(-1)
  if (last === undefined) return undefined
  const sizes = last.from === undefined ? '' : ` · ${fmtTok(last.from)} → ${last.to === undefined ? '…' : fmtTok(last.to)}`
  const times = list!.length > 1 ? `compacted ${list!.length}×, last ` : 'compacted '
  return `${times}${fmtMin(now - last.at)} ago${sizes}`
}

/**
 * What the pane shows that moves with the clock alone, written as the pane writes it.
 * The meter draws the pane again only when this changes: a quiet pane, once a minute.
 */
export function clockText(d: Pick<ViewData, 'now' | 'core' | 'series' | 'sources' | 'prefs' | 'viewedAgentId'>): string {
  const core = d.core
  if (core === null) return ''
  const burn = burnPerMin(d.series, d.now)
  const parts = [fmtMin(d.now - core.startedAt), fmtUsd(burn), fmtUsd(burn * 60)]
  if (core.turn !== null && core.turn.endedAt === undefined) parts.push(fmtDur(d.now - core.turn.startedAt))
  for (const l of core.limits) parts.push(l.resetsAt === undefined ? '' : fmtMin(Date.parse(l.resetsAt) - d.now))
  for (const w of Object.values(core.windows)) {
    const p = pace(w, d.now)
    const full = p?.fullAt === undefined ? '' : `${fmtEta(p.fullAt - d.now)} ${p.fullAt - d.now < 60 * 60_000}`
    parts.push(p === undefined ? '' : `${p.perMin > 0} ${p.isShort} ${full}`)
  }
  parts.push(compactionNote(core.compactions, d.now) ?? '')
  // The chart moves a bucket at a time while a bar or a mark is in sight.
  const bars = barsOf(d.series, d.now, 240, (core.compactions ?? []).map(c => c.at))
  if (bars.some(b => barTotal(b) > 0 || b.isCompacted)) parts.push(String(Math.floor(d.now / d.series.bucketMs)))
  const selected = d.prefs.selected ?? (d.viewedAgentId === undefined ? null : `agent:${d.viewedAgentId}`)
  const s = selected === null ? undefined : d.sources.rows[selected]
  if (s?.status === 'running' && s.kind !== 'main' && d.now - s.lastAt >= 5000) parts.push(fmtDur(d.now - s.lastAt))
  return parts.join('|')
}

export function drawPane(ui: Ui, art: Art | undefined, d: ViewData, act: ViewActions): RenderElement {
  const { Box, Text, Button } = ui
  const W = Math.max(24, d.width - 2) // the root Box pads a cell each side
  const core = d.core
  const tick = d.live.tick
  const sourceRows = Object.values(d.sources.rows)
  const tokens = sumTokens(sourceRows)
  const allTokens = tokens.in + tokens.out + tokens.cr + tokens.cw
  const hero = heroValue(d, allTokens)
  const budget = d.prefs.budget
  const usd = core?.usd ?? 0
  const budgetFrac = budget === null || budget <= 0 ? undefined : usd / budget
  const heroColor = budgetFrac === undefined ? 'claude' : budgetFrac >= 1 ? 'error' : budgetFrac >= 0.8 ? 'warning' : 'claude'
  const isBusy = d.live.inflight > 0
  const main = d.sources.rows['main']
  const isInline = d.placement === 'inline'
  const look = looksOf(d.caps)

  const heading = (text: string, right?: string) => (
    <Box justifyContent="space-between" marginTop={1}>
      <Text {...look.strong} color="subtle">
        {text}
      </Text>
      {right !== undefined && <Text dimColor>{right}</Text>}
    </Box>
  )

  // ── header ──
  const header = (
    <Box justifyContent="space-between">
      <Box gap={2}>
        <Text {...look.strong} color="claude">
          ◆ spend
        </Text>
        {isBusy ? (
          <Text color="claude">
            {SPINNER[tick % SPINNER.length]} {d.live.inflight} {d.live.inflight === 1 ? 'request' : 'requests'} live
          </Text>
        ) : (
          <Text dimColor>idle</Text>
        )}
      </Box>
      <Text dimColor>{core === null ? '' : fmtMin(d.now - core.startedAt)}</Text>
    </Box>
  )

  if (core === null) {
    return (
      <Box flexDirection="column" paddingX={1}>
        {header}
        <Text dimColor>Measuring the session…</Text>
      </Box>
    )
  }

  // ── the total ──
  const brrr = d.live.flash?.kind === 'brrr' && d.live.flash.until > d.now
  const streaming = d.live.estUsd >= 0.0005 ? `+${fmtUsd(d.live.estUsd)} streaming` : undefined
  const total = (
    <Box flexDirection="column" marginTop={1}>
      {brrr ? (
        printer(Text, tick)
      ) : (
        <Box justifyContent="space-between">
          <Text {...look.hero} color={heroColor}>
            {hero.text}
          </Text>
          {streaming !== undefined && (
            <Text {...look.num} color="claude">
              {streaming}
            </Text>
          )}
        </Box>
      )}
      <Button key="caption" plain dimColor onPress={act.cycleUnit}>
        {hero.caption} ⇄
      </Button>
    </Box>
  )

  // ── the turn, the pace, the budget ──
  const turn = core.turn
  const turnUsd = turn === null ? 0 : (turn.usd1 ?? core.usd) - turn.usd0
  const turnMs = turn === null ? 0 : (turn.endedAt ?? d.now) - turn.startedAt
  const burn = burnPerMin(d.series, d.now)
  const statLine = (label: string, value: string, right: string, color?: string) => (
    <Box justifyContent="space-between">
      <Box gap={1}>
        <Text {...look.table} dimColor>
          {label.padEnd(10)}
        </Text>
        <Text {...look.num} color={color}>
          {value}
        </Text>
      </Box>
      <Text dimColor>{right}</Text>
    </Box>
  )
  const budgetColor = budgetFrac === undefined ? undefined : budgetFrac >= 1 ? 'error' : budgetFrac >= 0.8 ? 'warning' : 'success'
  const [budgetOn, budgetOff] = gauge(Math.max(6, W - 27), budgetFrac ?? 0)
  const stats = (
    <Box flexDirection="column" marginTop={1}>
      {turn !== null &&
        statLine(
          turn.endedAt === undefined ? 'this turn' : 'last turn',
          `+${fmtUsd(turnUsd)}`,
          `${fmtDur(turnMs)}${turn.endedAt === undefined ? ' so far' : ''}`,
        )}
      {statLine('burn', burn < 0.0005 ? 'idle' : `${fmtUsd(burn)}/min`, burn < 0.0005 ? '' : `≈ ${fmtUsd(burn * 60)}/h`)}
      {budget !== null && budgetFrac !== undefined && (
        <Box justifyContent="space-between">
          <Box gap={1}>
            <Text dimColor>{'budget'.padEnd(10)}</Text>
            <Text>
              <Text color={budgetColor}>{budgetOn}</Text>
              <Text dimColor>{budgetOff}</Text>
            </Text>
          </Box>
          <Text color={budgetColor}>
            {fmtPct(budgetFrac * 100)} of {fmtUsd(budget)}
          </Text>
        </Box>
      )}
    </Box>
  )

  // ── over time ──
  const spanMin = Math.round((W * d.series.bucketMs) / 60_000)
  const bars = barsOf(
    d.series,
    d.now,
    W,
    (core.compactions ?? []).map(c => c.at),
  )
  const peak = Math.max(...bars.map(barTotal))
  const chartRows = Math.min(7, Math.max(3, Math.floor((d.rows - 30) / 3)))
  const kinds = (['main', 'agent', 'workflow'] as const).filter(k =>
    bars.some(b => (k === 'main' ? b.main : k === 'agent' ? b.agents : b.workflows) > 0),
  )
  let chart: RenderElement
  if (peak <= 0) {
    chart = <Text dimColor>No spend in the last {spanMin} minutes.</Text>
  } else if (art !== undefined && d.gfx === 'pixels') {
    chart = art.Image({ key: 'chart', source: areaPixels(bars, chartRows), columns: W, rows: chartRows, alt: areaText(bars) })
  } else if (art !== undefined) {
    chart = art.Raster({ key: 'chart', columns: W, rows: chartRows, cells: packCells(areaCells(bars, chartRows)) })
  } else {
    chart = <Text color="claude">{areaText(bars)}</Text>
  }
  const overTime = (
    <Box flexDirection="column">
      {heading('OVER TIME', peak > 0 ? `last ${spanMin} min · peak ${fmtUsd(peak)}/${Math.round(d.series.bucketMs / 1000)}s` : `last ${spanMin} min`)}
      {chart}
      {kinds.length > 1 && (
        <Box flexWrap="wrap" columnGap={2}>
          {kinds.map(k => (
            <Text>
              <Text color={KIND_COLOR[k]}>■ </Text>
              <Text dimColor>{KIND_NAME[k]}</Text>
            </Text>
          ))}
        </Box>
      )}
    </Box>
  )

  // ── limits ──
  const gaugeW = Math.max(6, W - 21)
  const limitLines: RenderElement[] = []
  const note = (text: RenderElement | string) => (
    <Box paddingLeft={4}>
      <Text dimColor wrap="truncate-end">
        {text}
      </Text>
    </Box>
  )
  for (const l of core.limits) {
    const [on, off] = gauge(gaugeW, l.pct / 100)
    const resets = l.resetsAt === undefined ? '' : `↻ ${fmtMin(Date.parse(l.resetsAt) - d.now)}`
    limitLines.push(
      <Box justifyContent="space-between">
        <Box gap={1}>
          <Text {...look.strong} {...look.table}>
            {windowName(l.kind).padEnd(3)}
          </Text>
          <Text>
            <Text color={pctColor(l.pct)}>{on}</Text>
            <Text dimColor>{off}</Text>
          </Text>
          <Text {...look.table} color={pctColor(l.pct)}>
            {fmtPct(l.pct).padStart(4)}
          </Text>
        </Box>
        <Text dimColor>{resets}</Text>
      </Box>,
    )
    const w = core.windows[l.kind]
    if (w === undefined || isInline) continue
    const moved = windowMoved(w)
    const p = pace(w, d.now)
    if (moved < 0.05 && (p === undefined || p.perMin <= 0)) continue
    const parts: RenderElement[] = [<Text dimColor>+{moved.toFixed(1)} pts since start</Text>]
    if (p !== undefined && p.perMin > 0 && p.fullAt !== undefined) {
      parts.push(
        p.isShort ? (
          <Text color={p.fullAt - d.now < 60 * 60_000 ? 'error' : 'warning'}> · full in ~{fmtEta(p.fullAt - d.now)} ⚠</Text>
        ) : (
          <Text color="success"> · pace ok</Text>
        ),
      )
    }
    limitLines.push(note(<Text>{parts}</Text>))
  }
  if (core.ctxPct !== undefined) {
    const [on, off] = gauge(gaugeW, core.ctxPct / 100)
    limitLines.push(
      <Box justifyContent="space-between">
        <Box gap={1}>
          <Text {...look.strong}>ctx</Text>
          <Text>
            <Text color={pctColor(core.ctxPct)}>{on}</Text>
            <Text dimColor>{off}</Text>
          </Text>
          <Text {...look.table} color={pctColor(core.ctxPct)}>
            {fmtPct(core.ctxPct).padStart(4)}
          </Text>
        </Box>
        <Text dimColor>
          {fmtTok(core.ctxTokens ?? 0)}/{fmtTok(core.ctxWindow)}
        </Text>
      </Box>,
    )
    const tax = ((core.ctxTokens ?? 0) * readRate(main?.model)) / 1e6
    if (tax > 0 && !isInline) limitLines.push(note(`≈ ${fmtUsd(tax)} to re-read per main request`))
  }
  // The same mark the chart draws where the session compacted, with or without the gauge:
  // from a compaction until the next response the context is unknown.
  const compacted = compactionNote(core.compactions, d.now)
  if (compacted !== undefined && !isInline) {
    limitLines.push(
      note(
        <Text>
          <Text color={hex(PALETTE.mark)}>│ </Text>
          {compacted}
        </Text>,
      ),
    )
  }

  // ── where it goes ──
  const rows = rowsOf(d)
  const costW = 8
  const barW = W >= 36 ? 7 : 0
  const labelW = Math.max(6, W - 1 - 2 - costW - barW)
  // Shares of what the meter watched: the spend before it has no bar.
  const watched = Math.max(0.000001, rows.reduce((a, r) => a + (r.kind === 'earlier' ? 0 : r.usd), 0))
  const maxRows = isInline ? 3 : Math.max(4, d.rows - 34)
  const selected = d.prefs.selected ?? (d.viewedAgentId === undefined ? null : `agent:${d.viewedAgentId}`)
  const sourceLines: RenderElement[] = []
  for (const r of rows.slice(0, maxRows)) {
    const isSel = selected === r.key
    // The engine's own calls, named in full where the row has room.
    const label = r.kind === 'overhead' && r.label.length > labelW ? 'side calls' : r.label
    // The row's share as a thin gauge, the limits' kind: a proportion, not a badge.
    const [shareOn, shareOff] = barW === 0 || r.kind === 'earlier' ? ['', ''] : gauge(barW - 1, r.usd / watched)
    const cost = r.usd === 0 && r.isStreaming ? '…' : `${r.source?.isPriced === false ? '≥' : ''}${fmtUsd(r.usd)}`
    const children = [
      <Text color={colorOf(r)}>{glyphOf(r, tick)}</Text>,
      ` ${clip(label, labelW).padEnd(labelW)} `,
      <Text {...(isSel ? look.strong : {})}>{cost.padStart(costW)}</Text>,
      shareOn === '' && shareOff === '' ? '' : ' ',
      <Text color={colorOf(r)}>{shareOn}</Text>,
      <Text dimColor>{shareOff}</Text>,
    ]
    sourceLines.push(
      r.source !== undefined ? (
        <Button key={`src:${r.key}`} plain onPress={() => act.select(isSel ? null : r.key)}>
          <Text {...look.table}>{children}</Text>
        </Button>
      ) : (
        <Text {...look.table} dimColor={r.kind === 'earlier'}>
          {children}
        </Text>
      ),
    )
    if (isSel && r.source !== undefined) sourceLines.push(details(ui, look, r.source, d, W, act.view))
  }
  const hidden = rows.slice(maxRows)
  if (hidden.length > 0) {
    sourceLines.push(
      <Text dimColor>
        {'  '}+{hidden.length} more · {fmtUsd(hidden.reduce((a, r) => a + r.usd, 0))}
      </Text>,
    )
  }

  // ── what the tokens cost ──
  const cost = sumCost(sourceRows)
  const hit = cacheHit(tokens)
  const tokW = 7
  const tokenLabelW = Math.max(8, W - tokW - costW - 2)
  const isCacheOpen = d.prefs.selected === 'cache'
  const tokenRow = (label: string, n: number, usdOf: number, color?: string) => (
    <Text {...look.table}>
      <Text color={color}>{clip(label, tokenLabelW).padEnd(tokenLabelW)}</Text> {fmtTok(n).padStart(tokW)} {fmtUsd(usdOf).padStart(costW)}
    </Text>
  )
  const tokenLines = (
    <Box flexDirection="column">
      <Box justifyContent="space-between" marginTop={1}>
        <Text {...look.strong} color="subtle">
          TOKENS
        </Text>
        <Text {...look.table} dimColor>
          {'tokens'.padStart(tokW)} {'cost'.padStart(costW)}
        </Text>
      </Box>
      {tokenRow('written by models', tokens.out, cost.output)}
      {tokenRow('new input, cached', tokens.cw, cost.write)}
      {tokenRow('re-read from cache', tokens.cr, cost.read)}
      {tokens.in > 0 && tokenRow('uncached input', tokens.in, cost.input)}
      {hit !== undefined && cacheLine(Button, Text, look, hit, W, isCacheOpen, () => act.select(isCacheOpen ? null : 'cache'))}
      {hit !== undefined && isCacheOpen && (
        <Box paddingLeft={2} marginBottom={1}>
          <Text dimColor>{cacheExplained(sourceRows, tokens.cr, cost.read, main?.model)}</Text>
        </Box>
      )}
    </Box>
  )

  if (isInline) {
    return (
      <Box flexDirection="column" paddingX={1}>
        <Box justifyContent="space-between">
          <Box gap={1}>
            <Text {...look.strong} {...look.num} color={heroColor}>
              {hero.text}
            </Text>
            {turn !== null && <Text dimColor>this turn +{fmtUsd(turnUsd)}</Text>}
          </Box>
          <Text dimColor>{burn < 0.0005 ? 'idle' : `${fmtUsd(burn)}/min`}</Text>
        </Box>
        {limitLines}
        {sourceLines}
      </Box>
    )
  }

  return (
    <Box flexDirection="column" paddingX={1}>
      {header}
      {total}
      {stats}
      {overTime}
      {limitLines.length > 0 && heading(core.isSubscriber ? 'LIMITS' : 'CONTEXT', core.isSubscriber ? 'whole account' : undefined)}
      {limitLines}
      {heading('WHERE IT GOES')}
      {sourceLines.length > 0 ? sourceLines : <Text dimColor>Nothing yet.</Text>}
      {allTokens > 0 && tokenLines}
    </Box>
  )
}

/** "cache served 99% of input · excellent", a toggle for what that means. */
function cacheLine(Button: Ui['Button'], Text: Ui['Text'], look: Looks, hit: number, width: number, isOpen: boolean, toggle: () => void) {
  const lead = `cache served ${fmtPct(hit * 100)} of input · `
  const [word, color] = hitWord(hit)
  const gap = ' '.repeat(Math.max(1, width - lead.length - word.length - 1))
  return (
    <Button key="cache" plain onPress={toggle}>
      <Text dimColor>{lead}</Text>
      <Text color={color}>{word}</Text>
      <Text dimColor={!isOpen} {...(isOpen ? look.strong : {})}>
        {gap}?
      </Text>
    </Button>
  )
}

/** What the cache does, in this session's own figures. */
function cacheExplained(rows: readonly SpendSource[], reread: number, readCost: number, model: string | undefined): string {
  const atFull = rows.reduce((a, s) => a + (s.tok.cr * inputRate(s.model)) / 1e6, 0)
  const ratio = inputRate(model) > 0 ? readRate(model) / inputRate(model) : 0
  const rate = ratio > 0 ? ` at ${Number(ratio.toFixed(3))}× on ${modelName(model)}` : ' for a fraction of it'
  const saved =
    atFull > readCost
      ? ` Without the cache, the ${fmtTok(reread)} re-read tokens would have cost ≈ ${fmtUsd(atFull)}, not ${fmtUsd(readCost)}.`
      : ''
  return `Each request resends the whole conversation. New input is cached once, at 1.25–2× the input price; later requests re-read it${rate}.${saved}`
}

function details(ui: Ui, look: Looks, s: SpendSource, d: ViewData, width: number, view: ViewActions['view']): RenderElement {
  const { Box, Text, Button } = ui
  const now = d.now
  const agentId = s.kind === 'agent' ? s.key.slice('agent:'.length) : undefined
  const isViewed = agentId !== undefined && d.viewedAgentId === agentId
  const hit = cacheHit(s.tok)
  const perStep = s.steps === 0 ? 0 : s.usd / s.steps
  const members = Object.values(s.members ?? {}).sort((a, b) => b.usd - a.usd)
  // Inside the details' indent: two for the marker, a space, the name, a space, eight for the cost.
  const nameW = Math.max(6, width - 2 - 13)
  return (
    <Box flexDirection="column" paddingLeft={2} marginBottom={1}>
      <Text dimColor wrap="truncate-end">
        {s.type !== undefined && s.kind !== 'workflow' ? `${s.type} · ` : ''}
        {modelName(s.model)} · {s.steps} requests
        {s.lastAt - s.firstAt >= 1000 ? ` over ${fmtDur(s.lastAt - s.firstAt)}` : ''}
        {s.status === 'running' && s.kind !== 'main' && now - s.lastAt >= 5000 ? ` · quiet ${fmtDur(now - s.lastAt)}` : ''}
      </Text>
      <Text dimColor wrap="truncate-end">
        {fmtTok(s.tok.out)} out · {fmtTok(s.tok.cw)} cached · {fmtTok(s.tok.cr)} re-read
      </Text>
      <Text dimColor wrap="truncate-end">
        {fmtUsd(perStep)} per request{hit === undefined ? '' : ` · cache served ${fmtPct(hit * 100)}`}
      </Text>
      {members.length > 0 && <Text dimColor>{members.length} {members.length === 1 ? 'agent' : 'agents'}:</Text>}
      {members.slice(0, 6).map(m => (
        <Text {...look.table} dimColor wrap="truncate-end">
          {'  '}
          {m.status === 'running' ? '●' : m.status === 'failed' ? '✗' : '✓'} {clip(m.label, nameW).padEnd(nameW)}{' '}
          {fmtUsd(m.usd).padStart(8)}
        </Text>
      ))}
      {members.length > 6 && <Text dimColor>{'  '}+{members.length - 6} more</Text>}
      {agentId !== undefined && d.caps.agentView && (
        <Button key={`view:${agentId}`} plain dimColor onPress={() => view(isViewed ? undefined : agentId)}>
          {isViewed ? '← back to the main conversation' : '↗ show its transcript'}
        </Button>
      )}
    </Box>
  )
}

function printer(Text: Ui['Text'], tick: number): RenderElement {
  const belt = '  $  ▓▓  $  ▓▓  $  ▓▓  $  ▓▓'
  const at = tick % 8
  const bills = belt.slice(at, at + 13).padEnd(13)
  return (
    <Text color="success">
      {'╭───────────────╮\n'}
      {`│ ${bills} │  b${'r'.repeat(2 + (tick % 5))}\n`}
      {'╰─┬───────────┬─╯\n'}
      {'  ┷           ┷  '}
    </Text>
  )
}

/** The one-line status chip shown under the prompt while the pane is closed. */
export function chipText(core: SpendCore | null, live: SpendLive): string | undefined {
  if (core === null) return undefined
  const parts = [`◆ ${fmtUsd(core.usd)}`]
  if (core.turn !== null) parts.push(`turn +${fmtUsd((core.turn.usd1 ?? core.usd) - core.turn.usd0)}`)
  for (const l of core.limits) {
    if (l.kind === 'five_hour' || l.kind === 'seven_day') parts.push(`${windowName(l.kind)} ${fmtPct(l.pct)}`)
  }
  if (live.inflight > 1) parts.push(`${live.inflight} live`)
  return `${parts.join(' · ')}  (/spend)`
}

